const EXPOOL = ['cour', 'edx', 'udem', 'yt', 'gla', 'swy', 'una', 'pw', 'ted', 'say', 'ol', 'fl', 'ali', 'li', 'int', 'sim', 'upg', 'kan', 'mit', 'cc', 'gfg', 'gdg'];
for (const [cat, txt] of Object.entries(EXTRA)) {
    for (const item of txt.split(';').map(x => x.trim()).filter(Boolean)) {
        const [topic, skills = '', flag = 'a'] = item.split('|');
        const pool = (NEWPOOL[cat] || []).concat(POOL[cat] || [], EXPOOL);
        const pick = new Set(['cour', 'yt', 'udem', 'gla']);
        const start = hash(topic) % pool.length;
        for (let k = 0; pick.size < 12 && k < pool.length; k++) {
            pick.add(pool[(start + k) % pool.length]);
        }
        for (const key of pick) {
            const kk = topic + '|' + key;
            if (!seen.has(kk)) {
                seen.add(kk);
                rows.push([topic, P[key], cat, flag, skills]);
            }
        }
    }
}

const out = path.join(__dirname, '..', 'public', 'catalog', 'catalog-courses.json');
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, JSON.stringify({ v: 1, rows }));
console.log(`catalog-courses.json: ${rows.length} courses, ${(fs.statSync(out).size / 1024).toFixed(0)} KB`);
const topics = new Set(rows.map(r => r[0]));
