const CITIES = ['Bengaluru', 'Hyderabad', 'Pune', 'Mumbai', 'Delhi', 'Gurugram', 'Noida', 'Chennai', 'Kolkata', 'Ahmedabad', 'Kochi', 'Jaipur', 'Chandigarh', 'Indore', 'Coimbatore', 'Bhubaneswar', 'Lucknow'];
const BIG = ['Bengaluru', 'Hyderabad', 'Pune', 'Mumbai', 'Delhi', 'Chennai'];
const jrows = [];
for (const item of R.split(';').map(x => x.trim()).filter(Boolean)) {
    const [role, cat, skills = ''] = item.split('|');
    // Bengaluru + 4 more cities (one of the big six always, the rest picked by the role's name) + remote
    const h = hash(role);
    const cs = new Set(['Bengaluru', BIG[1 + (h % 5)], CITIES[h % CITIES.length], CITIES[(h >> 3) % CITIES.length], CITIES[(h >> 6) % CITIES.length]]);
    const where = [...cs, ''];
    const iTitle = role + ' Intern';
    const jTitle = role + ' (Fresher)';
    for (const city of where) {
        jrows.push([iTitle, 'i', 0, city, cat, skills], [iTitle, 'i', 1, city, cat, skills]);
        jrows.push([jTitle, 'j', 2, city, cat, skills], [jTitle, 'j', 0, city, cat, skills]);
    }
    jrows.push([iTitle, 'i', 3, '', cat, skills]);
}
// PART 2: the same roles on the newer job boards (indexes 4 and up in BOARDS), appended after the rows above so old ids never change.
for (const item of R.split(';').map(x => x.trim()).filter(Boolean)) {
    const [role, cat, skills = ''] = item.split('|');
    const h = hash(role + 'b');
    const iTitle = role + ' Intern';
    const jTitle = role + ' (Fresher)';
    const cities = ['Bengaluru', BIG[(h >> 2) % 6], CITIES[(h >> 5) % CITIES.length], ''];
    for (let b = 0; b < 6; b++) {
        const bi = 4 + ((h + b * 5) % 12); // 12 new boards (4..15)
        for (const city of cities) {
            jrows.push([jTitle, 'j', bi, city, cat, skills]);
            if (b < 2) {
                jrows.push([iTitle, 'i', bi, city, cat, skills]);
            }
        }
    }
}
const outJ = path.join(__dirname, '..', 'public', 'catalog', 'catalog-jobs.json');
fs.writeFileSync(outJ, JSON.stringify({ v: 1, rows: jrows }));
console.log(`catalog-jobs.json: ${jrows.length} jobs and internships from ${R.split(';').length} roles, ${(fs.statSync(outJ).size / 1024).toFixed(0)} KB`);
